// Expo config plugin: Google Play upload signing for release builds.
//
// android/ is regenerated by `expo prebuild`, so the signing setup is injected
// here instead of edited by hand. The upload key lives OUTSIDE the repo in
// ~/keys/healthtracker-upload.properties (storeFile, storePassword, keyAlias,
// keyPassword). It is used only for `bundleRelease -PhealthTracker.playRelease=true`;
// every other build keeps Expo's default signing.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// play-upload-signing';

module.exports = function withPlayUploadSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes(MARKER)) return cfg;

    src = src.replace(
      /signingConfigs\s*\{/,
      `signingConfigs { ${MARKER}
        upload {
            def uploadProps = new Properties()
            def uploadPropsFile = new File(System.getProperty('user.home'), 'keys/healthtracker-upload.properties')
            if (uploadPropsFile.exists()) {
                uploadPropsFile.withInputStream { uploadProps.load(it) }
                storeFile file(uploadProps['storeFile'])
                storePassword uploadProps['storePassword']
                keyAlias uploadProps['keyAlias']
                keyPassword uploadProps['keyPassword']
            }
        }`
    );

    src = src.replace(
      /(release\s*\{[^}]*?)signingConfig signingConfigs\.debug/,
      `$1def playRelease = (findProperty('healthTracker.playRelease') ?: 'false').toBoolean()
            if (playRelease && !new File(System.getProperty('user.home'), 'keys/healthtracker-upload.properties').exists()) {
                throw new GradleException('Play release needs ~/keys/healthtracker-upload.properties')
            }
            signingConfig playRelease ? signingConfigs.upload : signingConfigs.debug`
    );

    cfg.modResults.contents = src;
    return cfg;
  });
};
